// 👇 Quer uma base maior? Acrescente anos aqui (igual a ANOS no notebook).
const ANOS = [2024, 2025, 2026];

return ANOS.map(ano => ({ json: { ano } }));

// Equivale a url_do_pdf() + o filtro "só leis com PDF" do notebook.
const BASE = 'https://www.teofilootoni.mg.leg.br';
const S3 = 'https://digitaliza-institucional.s3.us-east-2.amazonaws.com/';

const saida = [];
for (const item of $input.all()) {
  const lei = item.json;
  const caminho = lei.arquivo && lei.arquivo.path;
  if (!caminho) continue;                         // lei sem PDF: fica de fora

  saida.push({
    json: {
      id: lei.id,
      numero: String(lei.numero),
      ano: Number(lei.ano),
      ementa: lei.ementa || '',
      url_pdf: S3 + caminho.split('/').map(encodeURIComponent).join('/'),
      url_pagina: `${BASE}/legislacoes/show/${lei.id}`,
    },
  });
}
return saida;

// Porta da função limpar() do notebook (célula "3.4"): entidades HTML e espaços.
function limpar(texto) {
  texto = (texto || '')
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&amp;/g, '&');
  texto = texto.replace(/[ \t]+/g, ' ');      // vários espaços -> um só
  texto = texto.replace(/\n{3,}/g, '\n\n');   // 3+ quebras -> 2
  return texto.trim();
}

// Junta o texto extraído do PDF com os dados da lei (que vieram de "Preparar leis").
const saida = [];
$input.all().forEach((item, i) => {
  const lei = $('Preparar leis').itemMatching(i).json;
  const texto = limpar(item.json.text);
  if (texto.length < 200) return;                 // PDF vazio, só imagem ou download que falhou

  saida.push({
    json: {
      fonte: 'lei_municipal',
      referencia: `Lei nº ${lei.numero}/${lei.ano}`,
      numero: lei.numero,
      ano: lei.ano,
      ementa: limpar(lei.ementa),
      // A ementa vai junto do texto para também virar vetor (no notebook ela era
      // uma propriedade vetorizada à parte).
      texto: `${limpar(lei.ementa)}\n\n${texto}`,
      url_pdf: lei.url_pdf,
      url_pagina: lei.url_pagina,
    },
  });
});
return saida;

// Porta da função limpar() do notebook (célula "3.4"): entidades HTML e espaços.
function limpar(texto) {
  texto = (texto || '')
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&amp;/g, '&');
  texto = texto.replace(/[ \t]+/g, ' ');      // vários espaços -> um só
  texto = texto.replace(/\n{3,}/g, '\n\n');   // 3+ quebras -> 2
  return texto.trim();
}

// Porta de parse_lei_organica() do notebook: quebra a Lei Orgânica em artigos,
// guardando TÍTULO / CAPÍTULO / Seção e a página de cada um.
const LEI_ORGANICA_URL = 'https://digitaliza-institucional.s3.us-east-2.amazonaws.com/teofilo-otoni-camara-municipal/site/lei-organica-completa-com-emendas.pdf';

const RE_ARTIGO   = /^\s*Art\s*\.?\s*(\d+)\s*[-–ºo°.\s]/i;
const RE_TITULO   = /^\s*T[ÍI]TULO\s+([IVXL]+)\s*$/;
const RE_CAPITULO = /^\s*CAP[ÍI]TULO\s+([IVXL]+)\s*$/;
const RE_SECAO    = /^\s*Se[çc][ãa]o\s+([IVXL]+)\s*$/i;
const RE_NUM_PAG  = /^\s*\d{1,3}\s*$/;             // número de página solto

const ehMaiuscula = s => s === s.toUpperCase() && s !== s.toLowerCase();

// "Extrair páginas" entrega uma lista com o texto de cada página
const paginas = $input.first().json.text;
const listaPaginas = Array.isArray(paginas) ? paginas : [paginas];

// Achata tudo em [linha, número da página], descartando lixo
const linhas = [];
listaPaginas.forEach((textoPagina, idx) => {
  for (let linha of String(textoPagina || '').split('\n')) {
    linha = linha.replace(/[ \t]+/g, ' ').trimEnd();
    if (linha.trim() && !RE_NUM_PAG.test(linha)) linhas.push([linha, idx + 1]);
  }
});

// O documento começa com um sumário; o corpo começa no primeiro "TÍTULO I" sozinho
const inicio = linhas.findIndex(([linha]) => RE_TITULO.test(linha));
if (inicio < 0) throw new Error('Não achei o primeiro TÍTULO — o PDF mudou?');

let titulo = '', capitulo = '', secao = '';
let atual = null;
const artigos = [];

function fecharArtigo() {
  if (atual && atual.corpo.length) {
    atual.texto = limpar(atual.corpo.join('\n'));
    delete atual.corpo;
    artigos.push(atual);
  }
}

let i = inicio;
while (i < linhas.length) {
  const [linha, pagina] = linhas[i];
  const proxima = i + 1 < linhas.length ? linhas[i + 1][0].trim() : '';
  // o nome do TÍTULO/CAPÍTULO vem na linha seguinte, em maiúsculas
  const temNome = Boolean(proxima) && ehMaiuscula(proxima);
  let achou;

  if (RE_TITULO.test(linha)) {
    fecharArtigo(); atual = null;
    titulo = temNome ? `${linha.trim()} - ${proxima}` : linha.trim();
    capitulo = secao = '';
    i += temNome ? 2 : 1;
  } else if (RE_CAPITULO.test(linha)) {
    fecharArtigo(); atual = null;
    capitulo = temNome ? `${linha.trim()} - ${proxima}` : linha.trim();
    secao = '';
    i += temNome ? 2 : 1;
  } else if (RE_SECAO.test(linha)) {
    fecharArtigo(); atual = null;
    secao = proxima ? `${linha.trim()} - ${proxima}` : linha.trim();
    i += proxima ? 2 : 1;
  } else if ((achou = linha.match(RE_ARTIGO))) {
    fecharArtigo();
    const numero = Number(achou[1]);
    atual = { numero, titulo, capitulo, secao, pagina, corpo: [linha.trim()] };
    i += 1;
  } else {
    if (atual) atual.corpo.push(linha.trim());
    i += 1;
  }
}
fecharArtigo();

return artigos.map(a => {
  const contexto = [a.titulo, a.capitulo, a.secao].filter(Boolean).join(' > ');
  return {
    json: {
      fonte: 'lei_organica',
      referencia: `Art. ${a.numero}`,
      numero: String(a.numero),
      contexto,
      pagina: a.pagina,
      // O contexto vai junto do texto para também virar vetor.
      texto: `${contexto}\n\n${a.texto}`,
      url_pdf: LEI_ORGANICA_URL,
    },
  };
});
